package com.nimbus.settlement.domain.entity;

import com.nimbus.driver.domain.entity.DriverProfile;
import jakarta.persistence.*;
import lombok.*;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * Settlement entity representing driver payment for a period.
 *
 * <p>Settlement expression:
 * driver payable = gross passenger collections - platform commission
 *                 - platform-funded adjustments - refunds + driver credits
 *
 * <p>Generated by daily scheduled job. Previous-day driver due
 * blocks new eligibility until cleared.</p>
 */
@Entity
@Table(name = "settlements", indexes = {
    @Index(name = "idx_settlements_driver_id_period", columnList = "driver_id, period_start, period_end"),
    @Index(name = "idx_settlements_status", columnList = "status")
})
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Settlement {

    @Id
    @GeneratedValue
    private UUID id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "driver_id", nullable = false, foreignKey = @ForeignKey(name = "fk_settlement_driver"))
    private DriverProfile driver;

    @Column(name = "period_start", nullable = false)
    private Instant periodStart;

    @Column(name = "period_end", nullable = false)
    private Instant periodEnd;

    @Column(name = "gross_earnings", nullable = false, precision = 18, scale = 2)
    private BigDecimal grossEarnings;

    @Column(name = "commission", nullable = false, precision = 18, scale = 2)
    private BigDecimal commission;

    @Column(name = "adjustments", precision = 18, scale = 2)
    @Builder.Default
    private BigDecimal adjustments = BigDecimal.ZERO;

    @Column(name = "refunds", precision = 18, scale = 2)
    @Builder.Default
    private BigDecimal refunds = BigDecimal.ZERO;

    @Column(name = "driver_credits", precision = 18, scale = 2)
    @Builder.Default
    private BigDecimal driverCredits = BigDecimal.ZERO;

    @Column(name = "payable", nullable = false, precision = 18, scale = 2)
    private BigDecimal payable;

    @Column(name = "status", nullable = false, length = 20)
    @Enumerated(EnumType.STRING)
    @Builder.Default
    private SettlementStatus status = SettlementStatus.PENDING;

    @Column(name = "payment_reference", length = 255)
    private String paymentReference;

    @Column(name = "created_at", nullable = false)
    @Builder.Default
    private Instant createdAt = Instant.now();

    @Column(name = "updated_at", nullable = false)
    @Builder.Default
    private Instant updatedAt = Instant.now();

    public enum SettlementStatus {
        PENDING,       // Awaiting processing
        PROCESSING,    // Payment being processed
        PAID,          // Payment completed
        FAILED,        // Payment failed
        ON_HOLD        // On hold due to issues
    }

    /**
     * Calculate payable amount:
     * payable = gross - commission - adjustments - refunds + driver_credits
     */
    public BigDecimal calculatePayable() {
        return grossEarnings
                .subtract(commission)
                .subtract(adjustments)
                .subtract(refunds)
                .add(driverCredits);
    }

    /**
     * Check if settlement is ready for processing.
     */
    public boolean isReady() {
        return status == SettlementStatus.PENDING;
    }
}
